require __DIR__.'/app-bootstrap.php';$email=(string)($_SESSION['password_reset_email']??'');$error='';$done=false;if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{$challenge=verify_email_otp($email,'password_reset',(string)($_POST['code']??''));if(!$challenge)throw new RuntimeException('That code is invalid or expired.');$password=(string)($_POST['password']??'');if(strlen($password)<12)throw new RuntimeException('Use at least 12 characters.');$pdo->prepare('UPDATE users SET password_hash=? WHERE email=?')->execute([password_hash($password,PASSWORD_DEFAULT),$email]);unset($_SESSION['password_reset_email']);$done=true;}catch(Throwable $e){$error=$e->getMessage();}}layout_header('Password reset');?><form class="auth panel" method="post"><span class="kicker">ACCOUNT SECURITY</span><h1>Password reset</h1><?php if($done):?><p class="success">Password reset complete.</p><a class="button" href="<?=e(url('login'))?>">Sign in</a><?php else:?><p class="muted">Enter the code sent to <?=e($email)?> and choose a new password.</p><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><label>Verification code<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></label><label>New password<input name="password" type="password" minlength="12" autocomplete="new-password" required></label><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button">Reset password</button><?php endif;?></form><?php layout_footer();
